/* Business-in-a-Box — self-contained interactive demo.
   Data is stored in localStorage. No server or API keys required. */
(() => {
'use strict';
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const STORAGE = 'biab-workspace-v2';
const navItems = [
 ['dashboard','▦','Dashboard'],['crm','♟','CRM'],['website','◎','Website'],['bookings','▦','Booking System'],
 ['invoices','▤','Quotes & Invoices'],['payments','▣','Payments'],['customers','◉','Customer Database'],
 ['marketing','◉','Marketing'],['employees','♟','Employee Management'],['scheduling','▦','Scheduling'],
 ['accounting','⇄','Accounting Integrations'],['receptionist','◉','AI Receptionist'],['sales-agent','♧','AI Sales Agent'],
 ['support','☏','AI Customer Support'],['analytics','▥','Business Analytics'],['pricing','◇','Plans & Pricing'],['settings','⚙','Settings']
];
const seed = {
 company:'', owner:'', email:'', industry:'Home services', plan:'Starter',
 contacts:[], bookings:[], invoices:[], payments:[], employees:[], tasks:[], campaigns:[], activities:[],
 settings:{showPromo:true,aiEnabled:false,notifications:true,currency:'ZAR',businessEmail:'',website:''}
};
let state = loadState();
let currentView = location.hash.slice(1) || 'dashboard';
let crmTab = 'Contacts';
let selectedContact = null;
let tableSearch = '';
let modalAction = null;
let onboardingIndustry = state.industry;
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE));return saved?{...structuredClone(seed),...saved,settings:{...seed.settings,...saved.settings},contacts:saved.contacts||[],bookings:saved.bookings||[],invoices:saved.invoices||[],payments:saved.payments||[],employees:saved.employees||[],tasks:saved.tasks||[],activities:saved.activities||[],campaigns:saved.campaigns||[]}:structuredClone(seed)}catch{return structuredClone(seed)}}
let saveTimer;
function save(){
 localStorage.setItem(STORAGE,JSON.stringify(state));
 clearTimeout(saveTimer);
 saveTimer=setTimeout(async()=>{try{const r=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(state)});if(r.status===401)console.warn('Workspace is local-only until you sign in.')}catch(e){console.warn('Could not sync workspace; local copy retained.',e)}},250);
}
function money(n){return new Intl.NumberFormat('en-ZA',{style:'currency',currency:state.settings.currency||'ZAR',maximumFractionDigits:0}).format(n||0)}
function initials(name=''){return name.split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()}
function escapeHTML(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=msg;$('#toast-region').append(el);setTimeout(()=>el.remove(),3200)}
function navIcon(name){return navItems.find(x=>x[0]===name)?.[1]||'◈'}
function renderNav(){
 $('#main-nav').innerHTML=navItems.map((n,i)=>`${i===15?'<div class="nav-separator"></div>':''}<button class="nav-item ${currentView===n[0]?'active':''}" data-view="${n[0]}"><span class="nav-icon">${n[1]}</span><span>${n[2]}</span></button>`).join('');
 $('#mobile-bottom').innerHTML=[navItems[0],navItems[1],navItems[3],navItems[4],navItems[16]].map(n=>`<button data-view="${n[0]}" class="${currentView===n[0]?'active':''}"><span>${n[1]}</span>${n[2].replace(' & Invoices','')}</button>`).join('');
 $('#upgrade-card').hidden=!state.settings.showPromo || ['pricing'].includes(currentView);
}
function go(view){currentView=view;selectedContact=null;location.hash=view;renderNav();renderView();$('#sidebar').classList.remove('open');$('#main-content').focus({preventScroll:true});window.scrollTo({top:0,behavior:'smooth'})}
function heading(title,subtitle,icon='◈',actions=''){return `<div class="page-heading"><div class="heading-title"><span class="heading-icon">${icon}</span><div><h1>${title}</h1><div class="subheading">${subtitle}</div></div></div><div class="heading-actions">${actions}</div></div>`}
function btn(label,action,kind='primary',extra=''){return `<button class="btn btn-${kind}" data-action="${action}" ${extra}>${label}</button>`}
function panel(title,body,extra=''){return `<section class="panel ${extra}"><div class="panel-head"><h2>${title}</h2></div>${body}</section>`}
function stat(label,value,icon,trend,color=''){return `<article class="stat-card"><div class="stat-top"><span class="stat-icon ${color}">${icon}</span><span>${label}</span></div><div class="stat-value">${value}</div><div class="trend ${trend.startsWith('↓')?'negative':''}">${trend}</div></article>`}
function chartSVG(){
 const paid=state.invoices.filter(i=>i.status==='Paid');
 if(!paid.length)return '<div class="empty-state">Your revenue chart will appear here after you record your first paid invoice.</div>';
 const total=paid.reduce((sum,i)=>sum+(Number(i.amount)||0),0);
 const points=paid.slice(-7).map((i,n)=>({label:String(i.date||'').slice(5)||`Item ${n+1}`,value:Number(i.amount)||0}));
 const max=Math.max(...points.map(p=>p.value),1), coords=points.map((p,i)=>`${48+i*(456/Math.max(points.length-1,1))},${158-(p.value/max*110)}`).join(' ');
 return `<svg class="chart" viewBox="0 0 560 205" role="img" aria-label="Recorded paid invoices, total ${escapeHTML(money(total))}">${[35,75,115,155].map(y=>`<line x1="45" y1="${y}" x2="540" y2="${y}" stroke="#e8efff" stroke-dasharray="3 4"/>`).join('')}<polyline points="${coords}" fill="none" stroke="#2768ff" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>${points.map((p,i)=>`<text x="${48+i*(456/Math.max(points.length-1,1))}" y="184" text-anchor="middle" class="chart-label">${escapeHTML(p.label)}</text>`).join('')}</svg>`;
}
function activityHTML(a){return `<div class="activity-item"><div class="activity-symbol ${a.color||''}">${a.icon}</div><div class="activity-copy"><b>${escapeHTML(a.title)}</b><small>${escapeHTML(a.detail)}</small></div><span class="activity-time">${escapeHTML(a.time)}</span></div>`}
function appointmentHTML(b){return `<div class="appointment-row"><span class="appointment-time">${escapeHTML(b.time)}<br>${escapeHTML(b.date)}</span><div><b>${escapeHTML(b.title)}</b><small>${escapeHTML(b.person)}</small></div><span class="pill ${b.status==='Pending'?'pending':''}">${escapeHTML(b.status)}</span></div>`}
function quickAction(icon,title,desc,action,color=''){return `<button class="quick-action" data-action="${action}"><span class="stat-icon ${color}">${icon}</span><b>${title}</b><small>${desc}</small></button>`}
function dashboard(){
 const paid=state.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+i.amount,0);
 const outstanding=state.invoices.filter(i=>i.status==='Outstanding').reduce((s,i)=>s+i.amount,0);
 return `${heading(`Good morning, ${escapeHTML(state.owner.split(' ')[0])}! 👋`,"Here's what's happening with your business today.",'▦',`<select class="select-field" id="company-select"><option>${escapeHTML(state.company)}</option><option>+ Add workspace</option></select><button class="btn btn-ghost" data-action="new-booking">▦ &nbsp; New booking</button>`)}
 <div class="grid stats-grid">${stat('Total Revenue',money(paid),'▥',state.invoices.some(i=>i.status==='Paid')?'Recorded payments':'No payments recorded yet')}${stat('New Customers',state.contacts.filter(c=>c.type==='Customer').length,'♟','Customers added to your workspace','purple')}${stat('Appointments',state.bookings.length,'▦','Scheduled bookings','green')}${stat('Outstanding Invoices',money(outstanding),'▤','Awaiting payment','pink')}</div>
 <div class="grid dashboard-columns">
 <div class="stack">${panel('Revenue overview',`<div class="panel-head"><span class="subheading">Revenue activity · last 7 days</span><select class="select-field" id="chart-range"><option>Last 7 days</option><option>Last 30 days</option><option>This year</option></select></div>${chartSVG()}`,'chart-panel')}
 ${panel('Quick actions',`<div class="grid quick-grid">${quickAction('♟','Add customer','Create a new customer','new-contact')}${quickAction('▤','Create invoice','Send a quote or invoice','new-invoice','purple')}${quickAction('▦','Book appointment','Manage your schedule','new-booking','green')}${quickAction('◀','Send marketing','Create a campaign','marketing','pink')}${quickAction('♟','Add employee','Invite a team member','new-employee','purple')}${quickAction('▥','View reports','Business analytics','analytics')}${quickAction('▣','Accept payment','Online or in-person','payments','green')}${quickAction('◎','Manage website','Edit your website','website','purple')}</div>`)}
 </div>
 <div class="stack">${panel('Recent activity',`<div class="activity-list">${state.activities.slice(0,5).map(activityHTML).join('')||'<div class="empty-state">No activity yet. Your business activity will appear here as you use the app.</div>'}</div><button class="quiet-link" data-view="analytics">View all activity →</button>`)}
 ${panel('Upcoming appointments',`<div class="appointment-list">${state.bookings.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,4).map(appointmentHTML).join('')||'<div class="empty-state">No appointments yet. Create your first booking to get started.</div>'}</div>${btn('Manage schedule','scheduling','ghost')}`)}
 </div>
 <div class="stack"><section class="assistant-panel"><div class="assistant-title"><div class="bot-face">🤖</div><div><h2>AI Assistant</h2><p>Your 24/7 business helper</p></div></div><div class="chat-bubble" id="assistant-response">Hi ${escapeHTML(state.owner.split(' ')[0])}! 👋<br>I can help with customer enquiries, bookings, follow-ups, and more.</div><button class="suggestion" data-prompt="Summarise today's appointments">▦ &nbsp; Summarise today's appointments</button><button class="suggestion" data-prompt="Help me draft a marketing post">◀ &nbsp; Help me draft a marketing post</button><button class="suggestion" data-prompt="Find a customer by name">♟ &nbsp; Find a customer by name</button><button class="suggestion" data-prompt="What's my revenue this week?">▥ &nbsp; What's my revenue this week?</button><form class="assistant-input" id="assistant-form"><input id="assistant-prompt" placeholder="Ask me anything…" aria-label="Ask AI assistant"><button aria-label="Send message">➜</button></form></section>
 ${panel('Business at a glance',`<div class="mini-metrics"><div class="mini-metric">♟<small>Customers</small><b>${state.contacts.length}</b></div><div class="mini-metric">▦<small>Appointments</small><b>${state.bookings.length}</b></div><div class="mini-metric">▤<small>Invoices</small><b>${state.invoices.length}</b></div><div class="mini-metric">♟<small>Team members</small><b>${state.employees.length}</b></div></div>`)}
 </div></div>
 <div style="margin-top:16px" class="grid bottom-summary">${panel('Built for your business',`<p class="subheading">A connected workspace that grows with your business.</p><div class="mini-metrics"><div class="mini-metric">⚙<small>Industry</small><b style="font-size:12px">${escapeHTML(state.industry)}</b></div><div class="mini-metric">◇<small>Plan</small><b style="font-size:12px">${escapeHTML(state.plan)}</b></div></div>`)}${panel('Business growth',`<div class="empty-state">Growth insights will appear when you have enough real business activity to measure.</div>`)}</div>
 ${state.settings.showPromo?`<section class="promo-banner" style="margin-top:16px"><div><h2>Let AI work for you</h2><p>Automate follow-ups, handle customer support and never miss an opportunity.</p></div>${btn('Explore AI features','receptionist','ghost')}</section>`:''}`;
}
function contactRows(list){return list.map(c=>`<tr><td><div class="person-cell"><span class="avatar">${initials(c.name)}</span><span><b>${escapeHTML(c.name)}</b><small>${escapeHTML(c.company||'Independent')}</small></span></div></td><td>${escapeHTML(c.email)}</td><td>${escapeHTML(c.phone)}</td><td><span class="pill ${c.type==='Lead'?'lead':'customer'}">${escapeHTML(c.type)}</span></td><td>${money(c.value)}</td><td><div class="row-actions"><button class="tiny-btn" data-action="view-contact" data-id="${c.id}">View</button><button class="tiny-btn" data-action="edit-contact" data-id="${c.id}">Edit</button><button class="tiny-btn" data-action="delete-contact" data-id="${c.id}">Delete</button></div></td></tr>`).join('')}
function crm(){
 const tabNames=['Contacts','Leads','Companies','Tasks','Communication'];
 let list=state.contacts.filter(c=>(crmTab==='Leads'?c.type==='Lead':crmTab==='Contacts'?true:crmTab==='Companies'?true:true));
 if(tableSearch)list=list.filter(c=>[c.name,c.company,c.email,c.phone,c.type].join(' ').toLowerCase().includes(tableSearch.toLowerCase()));
 return `${heading('CRM','Manage your customers, leads and relationships — all in one place.','♟',`${btn('↥ Import contacts','import-contacts','ghost')}${btn('+ Add contact','new-contact')}`)}
 <div class="tabs">${tabNames.map(t=>`<button class="tab ${crmTab===t?'active':''}" data-crm-tab="${t}">${t}</button>`).join('')}</div>
 ${crmTab==='Tasks'?tasksPage(true):crmTab==='Communication'?communicationPage():crmTab==='Companies'?companiesPage():`<div class="filters"><input class="field search-field" id="table-search" value="${escapeHTML(tableSearch)}" placeholder="⌕  Search contacts…"><select class="select-field" id="contact-filter"><option>All contacts</option><option>Customer</option><option>Lead</option></select><select class="select-field" id="contact-sort"><option>Newest first</option><option>Name A–Z</option><option>Highest value</option></select></div><div class="table-panel"><div class="table-scroll"><table><thead><tr><th>Name / Company</th><th>Email</th><th>Phone</th><th>Type</th><th>Lifetime value</th><th>Actions</th></tr></thead><tbody id="contact-rows">${contactRows(list)||''}</tbody></table></div>${list.length?`<div class="subheading" style="padding:13px 16px">Showing ${list.length} contacts</div>`:`<div class="empty-state">No contacts match this search.<br><button class="btn btn-ghost" data-action="new-contact" style="margin-top:12px">Add a contact</button></div>`}</div>`}`;
}
function customers(){return crm()}
function companiesPage(){const companies=[...new Set(state.contacts.map(c=>c.company).filter(Boolean))];return panel('Companies',`${btn('+ Add company','new-company')}<div class="table-scroll"><table><thead><tr><th>Company</th><th>Contacts</th><th>Potential / value</th><th>Actions</th></tr></thead><tbody>${companies.map(name=>`<tr><td><b>${escapeHTML(name)}</b></td><td>${state.contacts.filter(c=>c.company===name).length}</td><td>${money(state.contacts.filter(c=>c.company===name).reduce((a,c)=>a+c.value,0))}</td><td><button class="tiny-btn" data-action="search-company" data-name="${escapeHTML(name)}">View contacts</button></td></tr>`).join('')}</tbody></table></div>`)}
function tasksPage(){return `${panel('Tasks & follow-ups',`${btn('+ New task','new-task')}<div class="table-scroll"><table><thead><tr><th>Task</th><th>Owner</th><th>Due date</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td>${escapeHTML(t.title)}</td><td>${escapeHTML(t.owner)}</td><td>${escapeHTML(t.due)}</td><td><select class="select-field task-status" data-id="${t.id}">${['Open','In progress','Done'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="tiny-btn" data-action="delete-task" data-id="${t.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`)}`
}
function communicationPage(){return `${panel('Communication centre',`<p class="subheading">Keep every customer conversation moving from one place.</p><div class="grid quick-grid" style="margin-top:16px">${quickAction('✉','Email customer','Compose an email','compose-email')}${quickAction('◉','WhatsApp follow-up','Prepare a message','compose-message','green')}${quickAction('◀','Marketing campaign','Create a campaign','new-campaign','purple')}${quickAction('☏','Support inbox','Open support workspace','support','pink')}</div>`)}${panel('Recent communication',`<div class="activity-list">${state.activities.map(activityHTML).join('')}</div>`)}`}
function contactDetail(c){return `${heading(c.name,`${c.company} · ${c.type}`,'♟',`${btn('Edit contact','edit-contact','ghost',`data-id="${c.id}"`)}${btn('+ New task','new-task')}`)}<div class="grid detail-grid">${panel('Contact overview',`<div class="contact-detail-head"><span class="avatar">${initials(c.name)}</span><div><h2>${escapeHTML(c.name)}</h2><p class="subheading">${escapeHTML(c.company)}</p><span class="pill ${c.type==='Lead'?'lead':'customer'}">${c.type}</span></div></div><div class="contact-facts">${[['Email',c.email],['Phone',c.phone],['Company',c.company],['Location',c.location],['Customer value',money(c.value)],['Source',c.source],['Orders',c.orders],['Last contact',c.last]].map(([a,b])=>`<div class="fact"><small>${a}</small><b>${escapeHTML(String(b||'—'))}</b></div>`).join('')}</div><div style="margin-top:16px"><h3>Tags</h3><span class="pill neutral">${escapeHTML(c.tags||'No tags')}</span></div>`)}<div class="stack">${panel('Recent activity',`<div class="activity-list">${state.activities.slice(0,3).map(activityHTML).join('')}</div>`)}${panel('Quick actions',`<div class="stack">${btn('✉ Send message','compose-email','ghost')}${btn('▦ Book appointment','new-booking','ghost')}${btn('▤ Create invoice','new-invoice','ghost')}</div>`)}</div></div>`}
function tableFor(items,kind){if(kind==='invoices')return `<div class="table-panel"><div class="table-scroll"><table><thead><tr><th>Document</th><th>Client</th><th>Issue date</th><th>Due date</th><th>Total</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(i=>{const quote=i.recordType==='Quote';const paid=quote?0:Number(i.paidAmount||0);const balance=Math.max(0,Number(i.amount||0)-paid);return `<tr><td><b>${escapeHTML(i.number)}</b><small style="display:block;color:var(--muted);margin-top:4px">${escapeHTML(i.description)}</small><small>${quote?'Quote':'Invoice'}</small></td><td>${escapeHTML(i.client)}</td><td>${escapeHTML(i.date||'—')}</td><td>${escapeHTML(i.due||'—')}</td><td><b>${money(i.amount)}</b></td><td>${quote?'—':money(balance)}</td><td><span class="pill ${['Outstanding','Sent','Overdue'].includes(i.status)?'pending':i.status==='Draft'||i.status==='Declined'?'neutral':i.status==='Paid'||i.status==='Accepted'?'customer':''}">${escapeHTML(i.status)}</span></td><td><div class="row-actions"><button class="tiny-btn" data-action="edit-document" data-id="${i.id}">Edit</button>${quote?(i.status==='Accepted'?`<button class="tiny-btn" data-action="convert-quote" data-id="${i.id}">Invoice</button>`:`<button class="tiny-btn" data-action="quote-status" data-id="${i.id}">Status</button>`):`<button class="tiny-btn" data-action="record-payment-for" data-id="${i.id}">Payment</button>`}<button class="tiny-btn" data-action="print-invoice" data-id="${i.id}">Print</button></div></td></tr>`}).join('')}</tbody></table></div></div>`;
 if(kind==='bookings')return `<div class="table-panel"><div class="table-scroll"><table><thead><tr><th>Appointment</th><th>Customer</th><th>Date</th><th>Time</th><th>Status</th><th>Actions</th></tr></thead><tbody>${items.map(b=>`<tr><td><b>${escapeHTML(b.title)}</b><small style="display:block;color:var(--muted);margin-top:4px">${escapeHTML(b.notes||'')}</small></td><td>${escapeHTML(b.person)}</td><td>${b.date}</td><td>${b.time}</td><td><span class="pill ${b.status==='Pending'?'pending':''}">${b.status}</span></td><td><div class="row-actions"><button class="tiny-btn" data-action="edit-booking" data-id="${b.id}">Edit</button><button class="tiny-btn" data-action="booking-status" data-id="${b.id}">Status</button><button class="tiny-btn" data-action="delete-booking" data-id="${b.id}">Delete</button></div></td></tr>`).join('')}</tbody></table></div></div>`;
 return '';
}
function bookingsPage(){return `${heading('Booking system','Manage appointments, availability and customer bookings.','▦',btn('+ New booking','new-booking'))}<div class="grid stats-grid">${stat('Total bookings',state.bookings.length,'▦','All scheduled')}${stat('Confirmed',state.bookings.filter(b=>b.status==='Confirmed').length,'✓','Ready to go','green')}${stat('Pending',state.bookings.filter(b=>b.status==='Pending').length,'◷','Needs attention','purple')}${stat('Customers',new Set(state.bookings.map(b=>b.person)).size,'♟','With bookings','pink')}</div><div class="filters"><input class="field search-field" id="booking-search" placeholder="Search bookings…"><select class="select-field" id="booking-status-filter"><option>All statuses</option><option>Confirmed</option><option>Pending</option><option>Cancelled</option></select></div><div id="booking-table">${tableFor(state.bookings,'bookings')}</div>`}
function invoicesPage(){const docs=state.invoices;const quotes=docs.filter(i=>i.recordType==='Quote');const invoices=docs.filter(i=>i.recordType!=='Quote');const paid=invoices.reduce((s,i)=>s+Number(i.paidAmount||0),0);const outstanding=invoices.reduce((s,i)=>s+Math.max(0,Number(i.amount||0)-Number(i.paidAmount||0)),0);return `${heading('Quotes & invoices','Create quotes, approve work, issue invoices and track partial or full payments.','▤',`${btn('＋ New quote','new-quote','ghost')}${btn('＋ Create invoice','new-invoice')}`)}<div class="grid stats-grid">${stat('Quotes',quotes.length,'✎','Estimate and approval records','purple')}${stat('Invoices',invoices.length,'▤','Issued billing documents')}${stat('Payments received',money(paid),'✓','Recorded against invoices','green')}${stat('Outstanding balance',money(outstanding),'◷','Remaining to collect','pink')}</div><div class="filters"><input class="field search-field" id="invoice-search" placeholder="Search documents or clients…"><select class="select-field" id="invoice-filter"><option>All statuses</option><option>Draft</option><option>Sent</option><option>Accepted</option><option>Declined</option><option>Outstanding</option><option>Partially paid</option><option>Paid</option><option>Overdue</option></select></div><div id="invoice-table">${tableFor(docs,'invoices')}</div><p class="subheading" style="margin-top:12px">Payments recorded here are manual records only. Online card or bank payment processing is not connected yet.</p>`}
function genericList(view,title,subtitle,icon,items,columns,addAction){return `${heading(title,subtitle,icon,btn('+ Add new',addAction))}<div class="filters"><input class="field search-field" id="generic-search" placeholder="Search ${title.toLowerCase()}…"></div><div class="table-panel"><div class="table-scroll"><table><thead><tr>${columns.map(c=>`<th>${c[0]}</th>`).join('')}<th>Actions</th></tr></thead><tbody id="generic-rows">${items.map(item=>`<tr>${columns.map(c=>`<td>${escapeHTML(String(item[c[1]]??'—'))}</td>`).join('')}<td><button class="tiny-btn" data-action="edit-${view}" data-id="${item.id}">Edit</button> <button class="tiny-btn" data-action="delete-${view}" data-id="${item.id}">Delete</button></td></tr>`).join('')}</tbody></table></div></div>`}
function employeesPage(){
 const roleRows=[['Owner','Full access','Manage billing, settings, team and all records'],['Admin','Most modules','Manage records and team; billing access limited'],['Manager','CRM, bookings, quotes, tasks','Manage day-to-day operations'],['Staff','Assigned tasks and bookings','Work on assigned jobs; limited record editing'],['Read only','View permitted records','Can view permitted information without editing']];
 const roleTable=`<div class="table-scroll"><table><thead><tr><th>Role</th><th>Access level</th><th>Intended permissions</th></tr></thead><tbody>${roleRows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td>${r[2]}</td></tr>`).join('')}</tbody></table></div>`;
 const employeeList=genericList('employees','Team members','Employee records and invitation status.','♟',state.employees,[['Name','name'],['Role','role'],['Email','email'],['Status','status']],'new-employee');
 return `${heading('Employee management','Manage team records, role assignments and invitation tracking.','♟',`${btn('Export team CSV','export-employees','ghost')}${btn('+ Invite employee','new-employee')}`)}<div class="grid stats-grid">${stat('Team members',state.employees.length,'♟','All team','purple')}${stat('Active',state.employees.filter(e=>e.status==='Active').length,'✓','Marked active','green')}${stat('Invitations',state.employees.filter(e=>e.status==='Invited').length,'✉','Awaiting acceptance','pink')}${stat('Open tasks',state.tasks.filter(t=>t.status!=='Done').length,'▤','Across your team')}</div>${panel('Role and permission guide',`<p class="subheading" style="padding:0 18px 12px">Assign a role to each team record. This guide documents the intended access model; server-enforced individual logins and permissions are a later security milestone.</p>${roleTable}`)}${employeeList}<p class="subheading" style="margin-top:12px">Invitations are currently tracked in this workspace only. Sending invitation emails and granting separate employee logins are not connected yet.</p>`
}
function tasksPageFull(){return `${heading('Scheduling & tasks','Coordinate work, deadlines and follow-ups.','▦',btn('+ New task','new-task'))}${panel('Tasks',`<div class="table-scroll"><table><thead><tr><th>Task</th><th>Owner</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.tasks.map(t=>`<tr><td>${escapeHTML(t.title)}</td><td>${escapeHTML(t.owner)}</td><td>${t.due}</td><td><select class="select-field task-status" data-id="${t.id}">${['Open','In progress','Done'].map(s=>`<option ${t.status===s?'selected':''}>${s}</option>`).join('')}</select></td><td><button class="tiny-btn" data-action="delete-task" data-id="${t.id}">Delete</button></td></tr>`).join('')}</tbody></table></div>`)}`}
const featureInfo={
 website:['◎','Website builder','Create a polished business website, manage pages and capture leads.','Edit website','Edit website settings'],
 payments:['▣','Payments','Track incoming payments and connect a payment provider.','Record payment','Record payment'],
 marketing:['◀','Marketing','Plan campaigns, write content and follow up with customers.','Create campaign','new-campaign'],
 accounting:['⇄','Accounting integrations','Keep your books aligned with your invoicing and payment workflows.','Configure integration','Configure integration'],
 receptionist:['◉','AI receptionist','Offer always-on enquiry handling, appointment intake and FAQs.','Configure receptionist','Configure AI'],
 'sales-agent':['♧','AI sales agent','Qualify leads, prepare follow-ups and keep your pipeline moving.','Configure sales agent','Configure AI'],
 support:['☏','AI customer support','Organise customer requests, suggested replies and support follow-ups.','Open support inbox','Open support inbox'],
 analytics:['▥','Business analytics','Review revenue, customer growth, bookings and conversion.','View reports','View reports']
};
function websiteDefaults(){return {title:state.websiteTitle||state.company||'Your Business',tagline:state.websiteTagline||'Professional service. Personal care.',headline:state.websiteHeadline||`Welcome to ${state.company||'Your Business'}`,intro:state.websiteIntro||`We help customers with dependable ${String(state.industry||'business').toLowerCase()} services. Get in touch to discuss what you need.`,services:state.websiteServices||'Consultations\nAppointments\nRepairs & maintenance',cta:state.websiteCTA||'Request an appointment',email:state.settings.businessEmail||state.email||'',phone:state.websitePhone||'',color:state.websiteColor||'#245cff',about:state.websiteAbout||`At ${state.company||'our business'}, we believe in clear communication, reliable work and friendly service.`,pages:state.websitePages||'Home\nServices\nAbout\nContact'}}
function websiteDocument(c){const esc=escapeHTML;const services=String(c.services||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(c.title)}</title><meta name="description" content="${esc(c.intro)}"><style>*{box-sizing:border-box}body{margin:0;font:16px/1.6 Inter,system-ui,-apple-system,sans-serif;color:#12234b;background:#f6f9ff}header{padding:22px max(5vw,20px);display:flex;justify-content:space-between;align-items:center;background:white;border-bottom:1px solid #e3ebfa}header strong{font-size:20px}nav a{margin-left:18px;color:#34486e;text-decoration:none}.hero{padding:80px max(5vw,20px);background:linear-gradient(125deg,#fff,#edf3ff);text-align:center}.eyebrow{color:${esc(c.color)};font-weight:700;text-transform:uppercase;letter-spacing:.1em;font-size:12px}.hero h1{font-size:clamp(34px,6vw,60px);line-height:1.08;max-width:900px;margin:14px auto}.hero p{max-width:680px;margin:20px auto;color:#53688c}.button{display:inline-block;background:${esc(c.color)};color:white;text-decoration:none;padding:13px 22px;border-radius:10px;font-weight:700;margin-top:14px}.wrap{max-width:1100px;margin:auto;padding:54px 20px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:18px}.card{background:white;border:1px solid #e2eafa;border-radius:16px;padding:24px}.card h3{margin-top:0}footer{text-align:center;background:#10234d;color:white;padding:28px 20px}small{color:#7b8cab}@media(max-width:600px){header{align-items:flex-start;gap:12px;flex-direction:column}nav a{margin:0 12px 0 0}.hero{padding-top:52px;padding-bottom:52px}}</style></head><body><header><strong>${esc(c.title)}</strong><nav>${String(c.pages).split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>`<a href="#${encodeURIComponent(x.toLowerCase())}">${esc(x)}</a>`).join('')}</nav></header><main><section class="hero" id="home"><div class="eyebrow">${esc(c.tagline)}</div><h1>${esc(c.headline)}</h1><p>${esc(c.intro)}</p><a class="button" href="mailto:${esc(c.email)}">${esc(c.cta)}</a></section><section class="wrap" id="services"><h2>Our services</h2><div class="cards">${services.map(x=>`<article class="card"><h3>${esc(x)}</h3><p>Contact us to learn more about this service and arrange the next step.</p></article>`).join('')||'<article class="card">Add your services in the website builder.</article>'}</div></section><section class="wrap" id="about"><h2>About us</h2><p>${esc(c.about)}</p></section><section class="wrap" id="contact"><h2>Contact</h2><p>${esc(c.email||'Add your business email in the website builder.')}</p><p>${esc(c.phone)}</p><a class="button" href="mailto:${esc(c.email)}">Get in touch</a></section></main><footer>© ${new Date().getFullYear()} ${esc(c.title)} · Built with Business-in-a-Box</footer></body></html>`}
function websiteBuilder(){const c=websiteDefaults();const field=(name,label,value,type='text',full=false)=>`<div class="form-field ${full?'full':''}"><label for="site-${name}">${label}</label>${type==='textarea'?`<textarea id="site-${name}" data-site-field="${name}" rows="${name==='intro'||name==='about'?3:4}">${escapeHTML(value)}</textarea>`:`<input id="site-${name}" data-site-field="${name}" type="${type}" value="${escapeHTML(value)}">`}</div>`;return `${heading('Website builder','Build a simple, responsive website for your business. Edit the content and preview your changes live.','◎',`${btn('Preview website','website-preview','ghost')}${btn('Download HTML','website-export','ghost')}${btn('Save website','website-save')}`)}<div class="grid" style="grid-template-columns:minmax(300px, .9fr) minmax(360px,1.1fr);gap:18px;align-items:start"><section class="panel"><div class="panel-head"><h2>Website content</h2><span class="pill">${state.websiteSaved?'Saved':'Draft'}</span></div><p class="subheading">Changes are previewed on the right. Save to keep them in your workspace.</p><form id="website-form" class="form-grid">${field('title','Business / website name',c.title)}${field('tagline','Short tagline',c.tagline)}${field('headline','Main headline',c.headline,'text',true)}${field('intro','Introduction',c.intro,'textarea',true)}${field('services','Services (one per line)',c.services,'textarea',true)}${field('about','About your business',c.about,'textarea',true)}${field('cta','Main button text',c.cta)}${field('email','Contact email',c.email,'email')}${field('phone','Contact phone',c.phone,'tel')}${field('color','Brand colour',c.color,'color')}<div class="form-field full"><label>Navigation pages (one per line)</label><textarea data-site-field="pages" id="site-pages" rows="3">${escapeHTML(c.pages)}</textarea></div><div class="form-field full" style="display:flex;gap:8px;flex-wrap:wrap">${btn('Save changes','website-save')}${btn('Reset content','website-reset','ghost')}</div></form><p class="subheading" style="margin-top:12px">Note: saving stores the site configuration in your workspace. To make it publicly available, the website still needs hosting and a domain.</p></section><section class="panel"><div class="panel-head"><h2>Live preview</h2><span class="subheading">Responsive preview</span></div><div id="website-preview-frame" style="border:1px solid #dce7f7;border-radius:12px;overflow:hidden;background:#f6f9ff;min-height:650px"></div></section></div>`}
function renderWebsitePreview(){const host=$('#website-preview-frame');if(!host)return;const c=collectWebsiteFields();host.innerHTML=`<div style="font-family:Inter,system-ui,sans-serif;color:#12234b;background:#f6f9ff;min-height:620px"><header style="display:flex;justify-content:space-between;gap:12px;align-items:center;padding:18px;background:#fff;border-bottom:1px solid #e3ebfa"><strong>${escapeHTML(c.title)}</strong><span style="font-size:12px;color:#607394">${escapeHTML(c.pages.split(/\r?\n/).filter(Boolean).join(' · '))}</span></header><section style="text-align:center;padding:55px 22px;background:linear-gradient(125deg,#fff,#edf3ff)"><div style="font-size:11px;letter-spacing:.1em;text-transform:uppercase;font-weight:700;color:${escapeHTML(c.color)}">${escapeHTML(c.tagline)}</div><h1 style="font-size:clamp(28px,4vw,44px);line-height:1.12;margin:15px auto;max-width:680px">${escapeHTML(c.headline)}</h1><p style="max-width:600px;margin:0 auto;color:#53688c">${escapeHTML(c.intro)}</p><span style="display:inline-block;background:${escapeHTML(c.color)};color:#fff;border-radius:9px;padding:11px 17px;margin-top:20px;font-weight:700">${escapeHTML(c.cta)}</span></section><section style="padding:28px 20px"><h2>Our services</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px">${c.services.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(x=>`<div style="background:#fff;border:1px solid #e2eafa;border-radius:10px;padding:15px">${escapeHTML(x)}</div>`).join('')||'<div>Add services to preview them here.</div>'}</div><h2 style="margin-top:28px">About us</h2><p>${escapeHTML(c.about)}</p><h2>Contact</h2><p>${escapeHTML(c.email)} ${escapeHTML(c.phone)}</p></section></div>`}
function collectWebsiteFields(){const c=websiteDefaults();$$('[data-site-field]').forEach(el=>c[el.dataset.siteField]=el.value);return c}
function persistWebsiteFields(showToast=true){const c=collectWebsiteFields();state.websiteTitle=c.title;state.websiteTagline=c.tagline;state.websiteHeadline=c.headline;state.websiteIntro=c.intro;state.websiteServices=c.services;state.websiteAbout=c.about;state.websiteCTA=c.cta;state.websitePhone=c.phone;state.websiteColor=c.color;state.websitePages=c.pages;state.settings.website=state.settings.website||'';state.settings.businessEmail=c.email;state.websiteSaved=true;save();if(showToast)toast('Website content saved to your workspace');return c}
function featurePage(view){const [icon,title,desc,action,label]=featureInfo[view];let body='';
 if(view==='website')return websiteBuilder();
 if(view==='website')body=`<div class="grid feature-grid"><article class="feature-card"><span class="stat-icon">▧</span><h3>Website status</h3><p>Your website workspace is ready to configure.</p><span class="pill">Draft</span></article><article class="feature-card"><span class="stat-icon purple">◎</span><h3>Lead capture</h3><p>Contact forms can feed leads into your CRM workflow.</p><span class="pill">Available</span></article><article class="feature-card"><span class="stat-icon green">▤</span><h3>Pages</h3><p>Home, Services, About and Contact page starter structure.</p>${btn('Edit pages','website-pages','ghost')}</article></div>`;
 else if(view==='payments')body=`<div class="grid stats-grid">${stat('Received',money(state.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+i.amount,0)),'▣','Recorded payments','green')}${stat('Awaiting',money(state.invoices.filter(i=>i.status==='Outstanding').reduce((s,i)=>s+i.amount,0)),'◷','Outstanding','pink')}${stat('Payment methods','2','▤','Demo methods')}${stat('Currency',state.settings.currency,'◇','Workspace setting','purple')}</div>${panel('Recent transactions',`<div class="table-scroll"><table><thead><tr><th>Reference</th><th>Customer</th><th>Amount</th><th>Status</th></tr></thead><tbody>${state.invoices.map(i=>`<tr><td>${i.number}</td><td>${escapeHTML(i.client)}</td><td>${money(i.amount)}</td><td><span class="pill">${i.status}</span></td></tr>`).join('')}</tbody></table></div>${btn('＋ Record payment','record-payment')}`)}`;
 else if(view==='marketing')body=`<div class="grid feature-grid">${[['◀','Email campaigns','Draft and manage customer email campaigns.'],['♟','Audience segments','Target leads, customers or a custom group.'],['✎','Content studio','Draft a post or announcement with AI assistance.']].map(x=>`<article class="feature-card"><span class="stat-icon purple">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p>${btn('Open','new-campaign','ghost')}</article>`).join('')}</div>${panel('Campaign activity',`<div class="empty-state">Your campaign workspace is ready. Create your first campaign to get started.</div>`)}`;
 else if(view==='analytics')body=`<div class="grid stats-grid">${stat('Revenue',money(state.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+i.amount,0)),'▥','Based on paid invoices')}${stat('Customers',state.contacts.filter(c=>c.type==='Customer').length,'♟','Real customer records','purple')}${stat('Bookings',state.bookings.length,'▦','Real booking records','green')}${stat('Leads',state.contacts.filter(c=>c.type==='Lead').length,'↗','Contacts marked as leads','pink')}</div><div class="grid detail-grid">${panel('Revenue overview',chartSVG())}${panel('Customer mix',`<div class="mini-metrics"><div class="mini-metric"><small>Customers</small><b>${state.contacts.filter(c=>c.type==='Customer').length}</b></div><div class="mini-metric"><small>Leads</small><b>${state.contacts.filter(c=>c.type==='Lead').length}</b></div></div><p class="subheading" style="margin-top:15px">Tip: keep lead records updated to make your reports more useful.</p>`)}</div>`;
 else if(view==='accounting')body=`<div class="grid feature-grid">${[['QuickBooks','Accounting sync','Connect your bookkeeping workflow.'],['Xero','Accounting sync','Prepare your accounts for reconciliation.'],['CSV export','Data portability','Export invoices and contacts for your accountant.']].map(x=>`<article class="feature-card"><span class="stat-icon">${x[0]==='Xero'?'⇄':'▤'}</span><h3>${x[0]}</h3><p>${x[2]}</p>${btn(x[0]==='CSV export'?'Export invoices':'Connect','accounting-connect','ghost',`data-provider="${x[0]}"`)}</article>`).join('')}</div><p class="subheading">Provider connections are simulated in this standalone demo; live accounting credentials are not connected.</p>`;
 else if(view==='receptionist'||view==='sales-agent'||view==='support')body=`<div class="grid detail-grid"><section class="panel"><div class="panel-head"><h2>${title} workspace</h2><span class="pill ${state.settings.aiEnabled?'':'pending'}">${state.settings.aiEnabled?'Enabled in demo':'Paused'}</span></div><p class="subheading">${desc}</p><div class="form-field" style="margin-top:18px"><label>Business instructions</label><textarea id="ai-instructions" placeholder="Describe your services, tone, opening hours, and when to hand off to a person…">${escapeHTML(state[view+'Instructions']||'Be helpful, clear and friendly. Never promise pricing or availability without confirmation.')}</textarea></div><label class="check-row"><input type="checkbox" id="ai-enabled" ${state.settings.aiEnabled?'checked':''}> Enable this AI workflow in the demo</label>${btn('Save configuration','save-ai')}</section><section class="assistant-panel"><div class="assistant-title"><div class="bot-face">🤖</div><div><h2>Preview assistant</h2><p>Local demo responses</p></div></div><div class="chat-bubble" id="assistant-response">Hello! I can help answer general questions about ${escapeHTML(state.company)}. What would you like to know?</div><form class="assistant-input" id="assistant-form"><input id="assistant-prompt" placeholder="Try a question…"><button>➜</button></form></section></div>`;
 return `${heading(title,desc,icon,btn('＋ '+action,'feature-primary'))}${body}`;
}
function marketingPage(){
 const audienceCount=a=>a==='Customers'?state.contacts.filter(c=>c.type==='Customer').length:a==='Leads'?state.contacts.filter(c=>c.type==='Lead').length:state.contacts.length;
 const rows=state.campaigns.map(c=>`<tr><td><strong>${escapeHTML(c.title)}</strong><div class="subheading">${escapeHTML(c.channel||'Email')} · ${escapeHTML(c.audience)}</div></td><td>${audienceCount(c.audience)}</td><td><span class="pill ${c.status==='Sent'?'success':c.status==='Scheduled'?'customer':''}">${escapeHTML(c.status)}</span></td><td>${escapeHTML(c.updated||c.created||'—')}</td><td><button class="tiny-btn" data-action="edit-campaign" data-id="${c.id}">Edit</button> <button class="tiny-btn" data-action="campaign-status" data-id="${c.id}">${c.status==='Draft'?'Mark sent':c.status==='Scheduled'?'Mark sent':'Reopen draft'}</button> <button class="tiny-btn" data-action="delete-campaign" data-id="${c.id}">Delete</button></td></tr>`).join('');
 return `${heading('Marketing','Create campaigns, prepare content and organise your audience.','◀',`${btn('Export CSV','export-campaigns','ghost')}${btn('+ Create campaign','new-campaign')}`)}<div class="grid stats-grid">${stat('Campaigns',state.campaigns.length,'◀','Saved in workspace','purple')}${stat('Drafts',state.campaigns.filter(c=>c.status==='Draft').length,'✎','Ready for review')}${stat('Marked sent',state.campaigns.filter(c=>c.status==='Sent').length,'✓','Manual status only','green')}${stat('Contacts',state.contacts.length,'♟','Potential audience')}</div>${panel('Campaign workspace',state.campaigns.length?`<div class="table-panel"><div class="table-scroll"><table><thead><tr><th>Campaign</th><th>Audience size</th><th>Status</th><th>Updated</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div></div>`:`<div class="empty-state"><h3>Your first campaign starts here</h3><p>Create a campaign, choose an audience, draft your message and save it for review.</p>${btn('Create first campaign','new-campaign')}</div>`)}${panel('Content studio',`<p class="subheading" style="padding:0 18px 12px">Create a reusable promotional message for your business. Drafts are stored in your workspace. Sending, scheduling and delivery analytics require an email or marketing provider connection.</p><div class="grid quick-grid">${quickAction('✉','Email campaign','Prepare an email draft','new-campaign')}${quickAction('◉','Social post','Draft a social post','new-social-post','purple')}${quickAction('♟','Review audience','View CRM contacts','crm','green')}</div>`)}`;
}
function openCampaign(c=null,channel='Email') { openModal(c?'Edit campaign':'Create campaign',[{name:'title',label:'Campaign name',value:c?.title||'',required:true},{name:'channel',label:'Channel',options:['Email','Social post','SMS','Announcement'],value:c?.channel||channel,required:true},{name:'audience',label:'Audience',options:['All contacts','Customers','Leads'],value:c?.audience||'All contacts',required:true},{name:'subject',label:'Subject / headline',value:c?.subject||''},{name:'message',label:'Campaign message',type:'textarea',value:c?.message||'',full:true,required:true},{name:'status',label:'Status',options:['Draft','Scheduled','Sent'],value:c?.status||'Draft'}],d=>{const now=new Date().toISOString().slice(0,10);if(c)Object.assign(c,d,{updated:now});else state.campaigns.unshift({...d,id:Date.now(),created:now,updated:now});state.activities.unshift({icon:'◀',color:'purple',title:c?'Campaign updated':'Campaign draft created',detail:d.title,time:'Just now'});save();renderView();toast(c?'Campaign updated':'Campaign saved. Sending is not connected yet.')}); }
function pricingPage(){const plans=[['Starter','$49','month','For solo operators',['Core CRM & customer database','Website and booking tools','Quotes, invoices and payments','Basic analytics']],['Professional','$149','month','For growing teams',['Everything in Starter','Marketing and automations','Employee management','Accounting integrations']],['Business','$399','month','For established businesses',['Everything in Professional','Advanced reporting','AI receptionist and sales tools','Priority support']],['Enterprise / Franchise','$2,000–$20,000+','month','For multi-location operations',['Custom business workflows','Multi-location controls','Enterprise integrations','Dedicated onboarding']]];return `${heading('Simple, transparent pricing','Choose a plan that fits your business, with optional AI usage add-ons.','◇') }<div class="grid pricing-grid">${plans.map((p,i)=>`<article class="price-card ${i===1?'featured':''}">${i===1?'<span class="pill customer">Most popular</span>':''}<div><h2>${p[0]}</h2><p class="subheading" style="margin-top:7px">${p[3]}</p></div><div class="price">${p[1]}<small> / ${p[2]}</small></div><ul>${p[4].map(x=>`<li>${x}</li>`).join('')}</ul>${btn(state.plan===p[0]?'Current plan':'Choose '+p[0],'choose-plan',i===1?'primary':'ghost',`data-plan="${p[0]}"`)}</article>`).join('')}</div><p class="subheading" style="margin-top:18px">Prices are illustrative subscription tiers. AI usage may be billed separately. Payments and subscriptions are not processed in this standalone demo.</p>`}
function settingsPage(){return `${heading('Settings','Manage your workspace, profile and preferences.','⚙')}<div class="grid settings-layout"><nav class="settings-nav"><button class="active" data-settings-tab="general">General</button><button data-settings-tab="preferences">Preferences</button><button data-settings-tab="data">Data & privacy</button></nav><section class="panel" id="settings-panel"><h2>Workspace settings</h2><p class="subheading" style="margin:7px 0 18px">Personalise your Business-in-a-Box workspace.</p><form id="settings-form" class="form-grid"><div class="form-field"><label>Business name</label><input name="company" value="${escapeHTML(state.company)}" required></div><div class="form-field"><label>Business owner</label><input name="owner" value="${escapeHTML(state.owner)}" required></div><div class="form-field"><label>Industry</label><select name="industry">${['Home services','Professional services','Retail & ecommerce','Health & wellness','Hospitality','Education','Automotive','Construction','Other'].map(x=>`<option ${state.industry===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Currency</label><select name="currency">${['ZAR','USD','GBP','EUR'].map(x=>`<option ${state.settings.currency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-field"><label>Business email</label><input type="email" name="businessEmail" value="${escapeHTML(state.settings.businessEmail)}"></div><div class="form-field"><label>Website</label><input name="website" value="${escapeHTML(state.settings.website)}"></div><div class="form-field full"><label class="check-row"><input type="checkbox" name="showPromo" ${state.settings.showPromo?'checked':''}> Show promotional upgrade section</label><label class="check-row"><input type="checkbox" name="notifications" ${state.settings.notifications?'checked':''}> Enable in-app notifications</label><label class="check-row"><input type="checkbox" name="aiEnabled" ${state.settings.aiEnabled?'checked':''}> Enable AI demo features</label></div><div class="form-field full"><button class="btn btn-primary">Save settings</button> <button type="button" class="btn btn-ghost" data-action="reset-demo">Reset demo data</button></div></form></section></div>`}
function onboarding(){const types=[['Home services','🔧','Plumbers, electricians, cleaners and repair teams.'],['Professional services','💼','Consultants, agencies and independent professionals.'],['Retail & ecommerce','🛍️','Shops, online sellers and product businesses.'],['Health & wellness','🌿','Studios, practitioners and wellness providers.'],['Hospitality','☕','Cafes, venues and guest services.'],['Other','✨','Build a workflow for your specific industry.']];return `${heading('Configure your business','Choose your starting point. You can change this at any time.','◇')}<div class="panel"><h2>1. What kind of business do you run?</h2><p class="subheading" style="margin:8px 0 17px">We’ll tailor the workspace around your industry.</p><div class="grid onboarding-grid">${types.map(t=>`<button class="choice-card ${onboardingIndustry===t[0]?'selected':''}" data-industry="${t[0]}"><span>${t[1]}</span><b>${t[0]}</b><small>${t[2]}</small></button>`).join('')}</div><h2 style="margin-top:26px">2. Start with a workflow</h2><div class="grid onboarding-grid" style="margin-top:14px">${[['Get more customers','♟','Capture leads and follow up.','crm'],['Manage appointments','▦','Let customers request a booking.','bookings'],['Get paid faster','▤','Quote, invoice and track payments.','invoices']].map(t=>`<button class="choice-card" data-workflow="${t[3]}"><span>${t[1]}</span><b>${t[0]}</b><small>${t[2]}</small></button>`).join('')}</div><div style="display:flex;justify-content:flex-end;margin-top:20px">${btn('Configure my workspace →','finish-onboarding')}</div></div>`}
function renderView(){
 const main=$('#main-content');
 if(selectedContact){const c=state.contacts.find(x=>x.id===selectedContact);if(c){main.innerHTML=contactDetail(c);return}selectedContact=null}
 if(currentView==='dashboard')main.innerHTML=dashboard();
 else if(currentView==='crm'||currentView==='customers')main.innerHTML=crm();
 else if(currentView==='bookings'||currentView==='scheduling')main.innerHTML=currentView==='bookings'?bookingsPage():tasksPageFull();
 else if(currentView==='invoices')main.innerHTML=invoicesPage();
 else if(currentView==='employees')main.innerHTML=employeesPage();
 else if(currentView==='pricing')main.innerHTML=pricingPage();
 else if(currentView==='settings')main.innerHTML=settingsPage();
 else if(currentView==='configure')main.innerHTML=onboarding();
 else if(currentView==='marketing')main.innerHTML=marketingPage();
 else if(currentView==='payments'||currentView==='website'||currentView==='accounting'||currentView==='receptionist'||currentView==='sales-agent'||currentView==='support'||currentView==='analytics')main.innerHTML=featurePage(currentView);
 else main.innerHTML=dashboard();
 if(currentView==='website')renderWebsitePreview();
}
function openModal(title,fields,callback){
 $('#modal-title').textContent=title;modalAction=callback;
 $('#modal-body').innerHTML=`<div class="form-grid">${fields.map(f=>`<div class="form-field ${f.full?'full':''}"><label for="mf-${f.name}">${f.label}</label>${f.type==='textarea'?`<textarea id="mf-${f.name}" name="${f.name}" ${f.required?'required':''} placeholder="${f.placeholder||''}">${escapeHTML(f.value||'')}</textarea>`:f.options?`<select id="mf-${f.name}" name="${f.name}" ${f.required?'required':''}>${f.options.map(o=>`<option ${String(o)===String(f.value)?'selected':''}>${escapeHTML(o)}</option>`).join('')}</select>`:`<input id="mf-${f.name}" name="${f.name}" type="${f.type||'text'}" value="${escapeHTML(f.value||'')}" placeholder="${f.placeholder||''}" ${f.required?'required':''}>`}</div>`).join('')}</div>`;
 $('#modal').showModal();
}
$('#modal-form').addEventListener('submit',e=>{
 e.preventDefault();
 if(!e.submitter || e.submitter.id!=='modal-save')return;
 const data=Object.fromEntries(new FormData(e.currentTarget).entries());
 const action=modalAction;
 if(action)action(data);
 if($('#modal').open)$('#modal').close();
});
// Close/cancel controls are explicit buttons so HTML required-field validation never blocks them.
document.addEventListener('click',e=>{
 const close=e.target.closest('[data-modal-close]');
 if(close){e.preventDefault();const dialog=$('#modal');if(dialog?.open)dialog.close();modalAction=null;return;}
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});
$('#modal').addEventListener('close',()=>{modalAction=null;});
function newContact(c=null){openModal(c?'Edit contact':'Add contact',[{name:'name',label:'Full name',value:c?.name,required:true},{name:'company',label:'Company',value:c?.company},{name:'email',label:'Email address',type:'email',value:c?.email,required:true},{name:'phone',label:'Phone',value:c?.phone},{name:'type',label:'Contact type',options:['Customer','Lead'],value:c?.type||'Lead'},{name:'source',label:'Source',options:['Website','Referral','Marketing','Walk-in','Other'],value:c?.source||'Website'},{name:'value',label:'Lifetime value (number)',type:'number',value:c?.value||0},{name:'location',label:'Location',value:c?.location||''},{name:'tags',label:'Tags',value:c?.tags}],d=>{const email=d.email.trim().toLowerCase();if(state.contacts.some(x=>x.email.toLowerCase()===email&&x.id!==c?.id)){toast('A contact with this email already exists.',true);return}d.name=d.name.trim();d.email=email;d.value=Math.max(0,Number(d.value)||0);if(c)Object.assign(c,d);else state.contacts.unshift({...d,id:Date.now(),orders:0,last:'Just now'});state.activities.unshift({icon:'♟',color:'',title:c?'Contact updated':'New contact added',detail:d.name,time:'Just now'});save();renderView();toast(c?'Contact updated':'Contact added')})}
function newBooking(existing=null){if(!state.contacts.length){toast('Add a customer in CRM before creating a booking.',true);go('crm');return}openModal(existing?'Edit booking':'Create booking',[{name:'title',label:'Appointment / job',value:existing?.title,required:true},{name:'person',label:'Customer',options:state.contacts.map(c=>c.name),value:existing?.person,required:true},{name:'date',label:'Date',type:'date',value:existing?.date||new Date().toISOString().slice(0,10),required:true},{name:'time',label:'Time',type:'time',value:existing?.time||'09:00',required:true},{name:'status',label:'Status',options:['Confirmed','Pending','Cancelled'],value:existing?.status||'Confirmed'},{name:'notes',label:'Notes',value:existing?.notes||'',full:true}],d=>{if(existing)Object.assign(existing,d);else state.bookings.push({...d,id:Date.now()});state.activities.unshift({icon:'▦',color:'',title:existing?'Booking updated':'Booking created',detail:`${d.title} with ${d.person}`,time:'Just now'});save();renderView();toast(existing?'Booking updated':'Booking created')})}
function newInvoice(existing=null, quote=false){if(!state.contacts.length){toast('Add a customer in CRM before creating a document.',true);go('crm');return}const today=new Date().toISOString().slice(0,10);const fields=[{name:'client',label:'Customer',options:state.contacts.map(c=>c.name),value:existing?.client,required:true},{name:'description',label:quote?'Quote description':'Invoice description',value:existing?.description?.replace(/^QUOTE:\s*/,'')||'',required:true,full:true},{name:'amount',label:'Total amount (before tax)',type:'number',value:existing?.amount,required:true},{name:'date',label:'Issue date',type:'date',value:existing?.date||today,required:true},{name:'due',label:'Due date',type:'date',value:existing?.due||(quote?'':new Date(Date.now()+7*864e5).toISOString().slice(0,10)),required:!quote}];openModal(existing?'Edit '+(quote?'quote':'invoice'):(quote?'Create quote':'Create invoice'),fields,d=>{const amount=Number(d.amount);if(!Number.isFinite(amount)||amount<=0){toast('Enter an amount greater than zero.',true);return}if(d.due&&d.date&&d.due<d.date){toast('Due date cannot be earlier than the issue date.',true);return}if(existing){existing.client=d.client;existing.description=quote?'QUOTE: '+d.description:d.description;existing.amount=amount;existing.date=d.date;existing.due=d.due||'—';save();renderView();toast('Document updated');return}const id=Date.now();const prefix=quote?'QUO-':'INV-';state.invoices.unshift({id,client:d.client,description:quote?'QUOTE: '+d.description:d.description,amount,number:prefix+String(id).slice(-6),date:d.date,due:d.due||'—',status:'Draft',recordType:quote?'Quote':'Invoice',paidAmount:0,payments:[]});state.activities.unshift({icon:'▤',color:'purple',title:quote?'Quote created':'Invoice created',detail:`${d.client} · ${money(amount)}`,time:'Just now'});save();renderView();toast(quote?'Quote saved as a draft':'Invoice saved as a draft')})}
function recordPaymentFor(inv){if(!inv||inv.recordType==='Quote'){toast('Payments can only be recorded against invoices.',true);return}const balance=Math.max(0,Number(inv.amount||0)-Number(inv.paidAmount||0));if(balance<=0){toast('This invoice is already fully paid.');return}openModal('Record invoice payment',[{name:'amount',label:`Amount received (balance ${money(balance)})`,type:'number',required:true},{name:'date',label:'Payment date',type:'date',value:new Date().toISOString().slice(0,10),required:true},{name:'method',label:'Payment method',options:['Bank transfer','Card (recorded externally)','Cash','EFT','Other'],value:'Bank transfer'},{name:'reference',label:'Payment reference'}],d=>{const amount=Number(d.amount);if(!Number.isFinite(amount)||amount<=0||amount>balance){toast(`Enter a payment greater than zero and no more than ${money(balance)}.`,true);return}inv.payments=Array.isArray(inv.payments)?inv.payments:[];inv.payments.push({id:Date.now(),amount,date:d.date,method:d.method,reference:d.reference||''});inv.paidAmount=Number(inv.paidAmount||0)+amount;inv.status=inv.paidAmount>=Number(inv.amount)?'Paid':'Partially paid';state.activities.unshift({icon:'▣',color:'green',title:'Payment recorded',detail:`${inv.number} · ${money(amount)} via ${d.method}`,time:'Just now'});save();renderView();toast(inv.status==='Paid'?'Invoice fully paid':'Partial payment recorded')})}
function changeQuoteStatus(inv){const options=['Draft','Sent','Accepted','Declined'];const next=options[(options.indexOf(inv.status)+1)%options.length];inv.status=next;save();renderView();toast(`${inv.number} marked ${next}`)}
function convertQuote(inv){if(!inv||inv.recordType!=='Quote'||inv.status!=='Accepted'){toast('Only accepted quotes can be converted to invoices.',true);return}const id=Date.now();state.invoices.unshift({id,client:inv.client,description:inv.description.replace(/^QUOTE:\s*/,''),amount:Number(inv.amount),number:'INV-'+String(id).slice(-6),date:new Date().toISOString().slice(0,10),due:new Date(Date.now()+14*864e5).toISOString().slice(0,10),status:'Draft',recordType:'Invoice',paidAmount:0,payments:[],sourceQuote:inv.number});inv.convertedTo=state.invoices[0].number;save();renderView();toast(`Invoice ${state.invoices[0].number} created from accepted quote`)}
function newTask(){const owners=[state.owner||'Business owner',...state.employees.filter(e=>e.status==='Active').map(e=>e.name)];openModal('Create task',[{name:'title',label:'Task title',required:true,full:true},{name:'owner',label:'Assigned to',options:[...new Set(owners)],value:state.owner||owners[0],required:true},{name:'due',label:'Due date',type:'date',value:new Date().toISOString().slice(0,10),required:true},{name:'status',label:'Status',options:['Open','In progress','Done'],value:'Open'}],d=>{state.tasks.unshift({...d,id:Date.now(),createdAt:new Date().toISOString().slice(0,10)});save();renderView();toast('Task created and assigned')})}
function newEmployee(emp=null){openModal(emp?'Edit team member':'Invite team member',[{name:'name',label:'Full name',value:emp?.name,required:true},{name:'role',label:'Role',options:['Admin','Manager','Staff','Read only'],value:emp?.role||'Staff',required:true},{name:'email',label:'Work email',type:'email',value:emp?.email,required:true},{name:'status',label:'Status',options:['Invited','Active','Paused'],value:emp?.status||'Invited'},{name:'notes',label:'Responsibilities / notes',type:'textarea',value:emp?.notes||'',full:true}],d=>{const duplicate=state.employees.some(x=>x.id!==emp?.id&&String(x.email).toLowerCase()===d.email.toLowerCase());if(duplicate){toast('A team member with that email already exists.',true);return}if(emp)Object.assign(emp,d);else state.employees.push({...d,id:Date.now(),createdAt:new Date().toISOString().slice(0,10)});save();renderView();toast(emp?'Team member updated':'Team member record created. Invitation email is not sent in this version.')})}
function askAssistant(prompt){const p=(prompt||'').trim();if(!p)return;const lower=p.toLowerCase();let answer='I can help you organise your business. Try asking about bookings, invoices, customers or revenue.';if(lower.includes('appointment')||lower.includes('booking'))answer=`You have ${state.bookings.length} booking(s) recorded. ${state.bookings.filter(b=>b.status==='Pending').length} need confirmation. Upcoming: ${state.bookings.slice(0,3).map(b=>`${b.time} ${b.title} (${b.person})`).join('; ')||'no bookings yet'}.`;else if(lower.includes('revenue')||lower.includes('invoice')||lower.includes('paid'))answer=`There are ${state.invoices.length} invoices. Paid: ${money(state.invoices.filter(i=>i.status==='Paid').reduce((s,i)=>s+i.amount,0))}; outstanding: ${money(state.invoices.filter(i=>i.status==='Outstanding').reduce((s,i)=>s+i.amount,0))}.`;else if(lower.includes('customer')||lower.includes('name')||lower.includes('contact'))answer=`Your CRM currently has ${state.contacts.length} contacts: ${state.contacts.slice(0,5).map(c=>c.name).join(', ')}. Open CRM to search and manage records.`;else if(lower.includes('marketing')||lower.includes('post'))answer=`Draft idea for ${state.company}: “Looking for a reliable ${state.industry.toLowerCase()} team? We make it easy to get started. Get in touch today to discuss your needs.” Review and customise before publishing.`;else if(lower.includes('help')||lower.includes('what can'))answer='I can summarise appointments, check invoice totals, find customer records, or draft marketing copy. This assistant uses the records in your workspace; AI service integration is not connected yet.';$('#assistant-response').textContent=answer;$('#assistant-prompt').value='';}
function handleAction(action,el){
 const id=Number(el.dataset.id),c=state.contacts.find(x=>x.id===id),b=state.bookings.find(x=>x.id===id),inv=state.invoices.find(x=>x.id===id),emp=state.employees.find(x=>x.id===id);
 switch(action){
 case 'new-contact':newContact();break;case 'edit-contact':if(c)newContact(c);break;case 'view-contact':if(c){selectedContact=c.id;renderView();}break;
 case 'delete-contact':if(c){const linked=state.bookings.some(x=>x.person===c.name)||state.invoices.some(x=>x.client===c.name);if(linked){toast('This contact is linked to bookings or invoices. Update those records before deleting the contact.',true);break}if(confirm(`Delete contact ${c.name}? This cannot be undone.`)){state.contacts=state.contacts.filter(x=>x.id!==id);state.activities.unshift({icon:'♟',color:'',title:'Contact deleted',detail:c.name,time:'Just now'});save();renderView();toast('Contact deleted')}}break;
 case 'new-booking':newBooking();break;case 'edit-booking':if(b)newBooking(b);break;case 'new-invoice':newInvoice(null,false);break;case 'new-quote':newInvoice(null,true);break;case 'edit-document':if(inv)newInvoice(inv,inv.recordType==='Quote');break;case 'quote-status':if(inv&&inv.recordType==='Quote')changeQuoteStatus(inv);break;case 'convert-quote':if(inv)convertQuote(inv);break;case 'record-payment-for':if(inv)recordPaymentFor(inv);break;case 'new-task':newTask();break;case 'export-employees':{const csv='Name,Role,Email,Status,Notes\n'+state.employees.map(x=>[x.name,x.role,x.email,x.status,x.notes||''].map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');download('business-in-a-box-team.csv',csv,'text/csv');break}case 'new-employee':newEmployee();break;case 'edit-employees':if(emp)newEmployee(emp);break;case 'delete-employees':if(emp&&confirm(`Remove ${emp.name} from the team?`)){state.employees=state.employees.filter(x=>x.id!==id);save();renderView();toast('Team member removed')}break;
 case 'new-company':openModal('Add company',[{name:'name',label:'Company name',required:true}],d=>{toast(`Company "${d.name}" added. Add a contact to associate it.`)});break;
 case 'search-company':tableSearch=el.dataset.name;crmTab='Contacts';go('crm');break;
 case 'import-contacts':openModal('Import contacts',[{name:'csv',label:'Paste CSV rows (name,email,company,phone)',type:'textarea',placeholder:'Jane Doe,jane@example.com,Example Co,+27…',full:true,required:true}],d=>{let count=0;d.csv.split(/\r?\n/).filter(Boolean).forEach(line=>{const [name,email,company,phone]=line.split(',').map(x=>x.trim());if(name&&email){state.contacts.push({id:Date.now()+count,name,email,company,phone,type:'Lead',source:'Import',value:0,orders:0,last:'Just now',location:'',tags:''});count++}});save();renderView();toast(`${count} contact(s) imported`)});break;
 case 'invoice-status':if(inv)recordPaymentFor(inv);break;
 case 'print-invoice':if(inv){const w=window.open('','_blank');if(w){w.document.write(`<title>${inv.number}</title><style>body{font:16px Arial;padding:40px;color:#10234d}h1{color:#245cff}table{border-collapse:collapse;width:100%}td{padding:12px;border-bottom:1px solid #ddd}</style><h1>Business-in-a-Box</h1><h2>${inv.recordType==='Quote'?'Quote':'Invoice'} ${inv.number}</h2><table><tr><td>Client</td><td>${escapeHTML(inv.client)}</td></tr><tr><td>Description</td><td>${escapeHTML(inv.description)}</td></tr><tr><td>Total</td><td>${money(inv.amount)}</td></tr><tr><td>Paid</td><td>${money(inv.paidAmount||0)}</td></tr><tr><td>Balance</td><td>${money(Math.max(0,inv.amount-(inv.paidAmount||0)))}</td></tr><tr><td>Status</td><td>${inv.status}</td></tr><tr><td>Issue date</td><td>${inv.date}</td></tr><tr><td>Due date</td><td>${inv.due}</td></tr></table><script>window.print()<\/script>`);w.document.close()}else toast('Allow pop-ups to print this invoice',true)}break;
 case 'booking-status':if(b){b.status=b.status==='Confirmed'?'Pending':b.status==='Pending'?'Cancelled':'Confirmed';save();renderView();toast(`Booking marked ${b.status}`)}break;
 case 'delete-booking':if(b&&confirm('Delete this booking?')){state.bookings=state.bookings.filter(x=>x.id!==id);save();renderView();toast('Booking deleted')}break;
 case 'delete-task':if(confirm('Delete this task?')){state.tasks=state.tasks.filter(x=>x.id!==id);save();renderView();toast('Task deleted')}break;
 case 'new-campaign':openCampaign();break;case 'new-social-post':openCampaign(null,'Social post');break;case 'edit-campaign':{const c=state.campaigns.find(x=>x.id===Number(el.dataset.id));if(c)openCampaign(c);break;}case 'campaign-status':{const c=state.campaigns.find(x=>x.id===Number(el.dataset.id));if(c){c.status=c.status==='Draft'?'Sent':c.status==='Scheduled'?'Sent':'Draft';c.updated=new Date().toISOString().slice(0,10);save();renderView();toast(`Campaign marked ${c.status}. This does not send messages.`)}break;}case 'delete-campaign':{const c=state.campaigns.find(x=>x.id===Number(el.dataset.id));if(c&&confirm(`Delete campaign “${c.title}”?`)){state.campaigns=state.campaigns.filter(x=>x.id!==c.id);save();renderView();toast('Campaign deleted')}break;}case 'export-campaigns':{const csv='Name,Channel,Audience,Subject,Message,Status,Created,Updated\n'+state.campaigns.map(c=>[c.title,c.channel,c.audience,c.subject,c.message,c.status,c.created,c.updated].map(v=>'+String(v??).replace(/"/g,)+').join(',')).join('\n');download('business-in-a-box-campaigns.csv',csv,'text/csv');break;}
 case 'compose-email':case 'compose-message':openModal(action==='compose-email'?'Compose email':'Prepare customer message',[{name:'to',label:'Recipient',options:state.contacts.map(c=>c.email),required:true},{name:'subject',label:'Subject',value:action==='compose-email'?'Following up':'A quick follow-up'},{name:'message',label:'Message',type:'textarea',full:true,required:true}],d=>{state.activities.unshift({icon:'✉',color:'',title:'Message drafted',detail:`To ${d.to}: ${d.subject}`,time:'Just now'});save();toast('Message draft saved locally. Sending requires an email provider.')});break;
 case 'record-payment':{const open=state.invoices.filter(i=>i.recordType!=='Quote'&&Number(i.paidAmount||0)<Number(i.amount||0));if(!open.length){toast('Create an invoice with an outstanding balance first.',true);go('invoices');break}openModal('Record payment',[{name:'invoice',label:'Invoice',options:open.map(i=>i.number+' — '+i.client),required:true},{name:'amount',label:'Amount received',type:'number',required:true},{name:'date',label:'Payment date',type:'date',value:new Date().toISOString().slice(0,10),required:true},{name:'method',label:'Payment method',options:['Bank transfer','Card (recorded externally)','Cash','EFT','Other'],value:'Bank transfer'},{name:'reference',label:'Payment reference'}],d=>{const num=d.invoice.split(' — ')[0],selected=state.invoices.find(x=>x.number===num);if(!selected)return;const balance=Math.max(0,Number(selected.amount||0)-Number(selected.paidAmount||0)),amount=Number(d.amount);if(!Number.isFinite(amount)||amount<=0||amount>balance){toast(`Enter a payment greater than zero and no more than ${money(balance)}.`,true);return}selected.payments=Array.isArray(selected.payments)?selected.payments:[];selected.payments.push({id:Date.now(),amount,date:d.date,method:d.method,reference:d.reference||''});selected.paidAmount=Number(selected.paidAmount||0)+amount;selected.status=selected.paidAmount>=Number(selected.amount)?'Paid':'Partially paid';state.activities.unshift({icon:'▣',color:'green',title:'Payment recorded',detail:`${selected.number} · ${money(amount)} via ${d.method}`,time:'Just now'});save();renderView();toast(selected.status==='Paid'?'Invoice fully paid':'Partial payment recorded')});break;}
 case 'accounting-connect':if(el.dataset.provider==='CSV export'){const csv='Invoice,Client,Amount,Status,Issue date,Due date\n'+state.invoices.map(i=>[i.number,i.client,i.amount,i.status,i.date,i.due].map(v=>`"${String(v).replace(/"/g,'""')}"`).join(',')).join('\n');download('business-in-a-box-invoices.csv',csv,'text/csv');}else toast(`${el.dataset.provider} connection is a demo placeholder. Add credentials on a secure backend to connect live.`);break;
 case 'website-save':{persistWebsiteFields();renderWebsitePreview();break}
 case 'website-preview':{const c=collectWebsiteFields();const w=window.open('','_blank');if(w){w.document.open();w.document.write(websiteDocument(c));w.document.close();}else toast('Allow pop-ups to preview the website.',true);break}
 case 'website-export':{const c=persistWebsiteFields(false);download('business-in-a-box-website.html',websiteDocument(c),'text/html');break}
 case 'website-reset':if(confirm('Reset the website content to its starter text?')){['websiteTitle','websiteTagline','websiteHeadline','websiteIntro','websiteServices','websiteAbout','websiteCTA','websitePhone','websiteColor','websitePages','websiteSaved'].forEach(k=>delete state[k]);save();renderView();toast('Website content reset');}break;
 case 'feature-primary':if(currentView==='website'){go('website');}else if(currentView==='payments')handleAction('record-payment',el);else if(currentView==='marketing')handleAction('new-campaign',el);else if(currentView==='accounting')toast('Choose an integration below to continue.');else go(currentView==='analytics'?'analytics':currentView);break;
 case 'website-pages':openModal('Edit website pages',[{name:'pages',label:'Pages (one per line)',type:'textarea',value:(state.websitePages||'Home\nServices\nAbout\nContact'),full:true}],d=>{state.websitePages=d.pages;save();toast('Website page list saved')});break;
 case 'configure':go('configure');break;
 case 'finish-onboarding':state.industry=onboardingIndustry;save();go('dashboard');toast(`Workspace configured for ${state.industry}`);break;
 case 'choose-plan':state.plan=el.dataset.plan;save();renderView();toast(`Demo plan set to ${state.plan}. No payment was taken.`);break;
 case 'save-ai':state[currentView+'Instructions']=$('#ai-instructions')?.value||'';state.settings.aiEnabled=$('#ai-enabled')?.checked??true;save();renderView();toast('AI configuration saved');break;
 case 'reset-demo':if(confirm('Clear all records in this workspace? This cannot be undone.')){state={...structuredClone(seed),company:state.company,owner:state.owner,email:state.email,industry:state.industry,plan:state.plan,settings:{...seed.settings,showPromo:state.settings.showPromo,currency:state.settings.currency}};save();go('dashboard');toast('Workspace records cleared')}break;
 case 'notifications':toast(state.settings.notifications?'You’re all caught up.':'Notifications are disabled in settings.');break;
 case 'profile-menu':openModal('Profile settings',[{name:'owner',label:'Display name',value:state.owner,required:true}],d=>{state.owner=d.owner;save();renderView();toast('Profile updated')});break;
 case 'pricing':go('pricing');break;case 'analytics':go('analytics');break;case 'website':go('website');break;case 'marketing':go('marketing');break;case 'payments':go('payments');break;case 'support':go('support');break;case 'receptionist':go('receptionist');break;
 default:toast('This action is available in the demo workspace.');
 }
}
function download(filename,text, type='text/plain'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);toast('Export ready')}
document.addEventListener('click',e=>{
 const viewEl=e.target.closest('[data-view]');if(viewEl){e.preventDefault();go(viewEl.dataset.view);return}
 const actionEl=e.target.closest('[data-action]');if(actionEl){e.preventDefault();handleAction(actionEl.dataset.action,actionEl);return}
 const tab=e.target.closest('[data-crm-tab]');if(tab){crmTab=tab.dataset.crmTab;tableSearch='';renderView();return}
 const industry=e.target.closest('[data-industry]');if(industry){onboardingIndustry=industry.dataset.industry;renderView();return}
 const workflow=e.target.closest('[data-workflow]');if(workflow){state.defaultWorkflow=workflow.dataset.workflow;$$('[data-workflow]').forEach(x=>x.classList.toggle('selected',x===workflow));toast('Workflow selected: '+workflow.querySelector('b').textContent);return}
 const prompt=e.target.closest('[data-prompt]');if(prompt){askAssistant(prompt.dataset.prompt);return}
 const st=e.target.closest('[data-settings-tab]');if(st){$$('[data-settings-tab]').forEach(x=>x.classList.toggle('active',x===st));toast(`${st.dataset.settingsTab[0].toUpperCase()+st.dataset.settingsTab.slice(1)} settings selected`);return}
});
document.addEventListener('change',e=>{
 if(e.target.id==='contact-filter'||e.target.id==='contact-sort'){const filter=$('#contact-filter')?.value||'All contacts',sort=$('#contact-sort')?.value||'Newest first';let list=state.contacts.filter(c=>filter==='All contacts'||c.type===filter);if(tableSearch)list=list.filter(c=>[c.name,c.company,c.email,c.phone,c.type].join(' ').toLowerCase().includes(tableSearch.toLowerCase()));if(sort==='Name A–Z')list.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='Highest value')list.sort((a,b)=>b.value-a.value);$('#contact-rows').innerHTML=contactRows(list);return}
 if(e.target.classList.contains('task-status')){const t=state.tasks.find(x=>x.id===Number(e.target.dataset.id));if(t){t.status=e.target.value;save();toast('Task status updated')}return}
 if(e.target.id==='booking-status-filter'||e.target.id==='booking-search'){filterBookings();return}
 if(e.target.id==='invoice-filter'||e.target.id==='invoice-search'){filterInvoices();return}
 if(e.target.id==='chart-range')toast(`Chart range changed to ${e.target.value}`);
 if(e.target.id==='company-select'&&e.target.value==='+ Add workspace'){openModal('Add workspace',[{name:'company',label:'Business name',required:true}],d=>{state.company=d.company;save();renderView();toast('Workspace created')})}
});
document.addEventListener('input',e=>{
 if(e.target.matches('[data-site-field]')){renderWebsitePreview();state.websiteSaved=false;const pill=$('.panel .pill');if(pill&&currentView==='website')pill.textContent='Unsaved changes';return}
 if(e.target.id==='table-search'){tableSearch=e.target.value;const filter=$('#contact-filter')?.value||'All contacts';let list=state.contacts.filter(c=>(filter==='All contacts'||c.type===filter)&&[c.name,c.company,c.email,c.phone,c.type].join(' ').toLowerCase().includes(tableSearch.toLowerCase()));$('#contact-rows').innerHTML=contactRows(list);return}
 if(e.target.id==='global-search'){const q=e.target.value.toLowerCase();if(e.key==='Enter')return;let old=$('#global-results');if(old)old.remove();if(q.length>1){const matches=state.contacts.filter(c=>[c.name,c.company,c.email].join(' ').toLowerCase().includes(q)).slice(0,5);const box=document.createElement('div');box.id='global-results';box.style.cssText='position:fixed;z-index:40;top:54px;left:50%;transform:translateX(-50%);width:min(510px,90vw);background:white;border:1px solid #dce7ff;border-radius:10px;padding:8px;box-shadow:0 12px 30px #10234d20';box.innerHTML=(matches.map(c=>`<button class="nav-item" data-action="view-contact" data-id="${c.id}">♟ &nbsp; ${escapeHTML(c.name)} <small>${escapeHTML(c.company)}</small></button>`).join('')||'<p class="subheading" style="padding:10px">No matching contacts.</p>')+`<button class="nav-item" data-view="crm">Open CRM →</button>`;document.body.append(box)}return}
});
function filterBookings(){const q=($('#booking-search')?.value||'').toLowerCase(),s=$('#booking-status-filter')?.value||'All statuses';const list=state.bookings.filter(b=>(s==='All statuses'||b.status===s)&&[b.title,b.person,b.date].join(' ').toLowerCase().includes(q));$('#booking-table').innerHTML=tableFor(list,'bookings')||'<div class="empty-state">No bookings found.</div>'}
function filterInvoices(){const q=($('#invoice-search')?.value||'').toLowerCase(),s=$('#invoice-filter')?.value||'All statuses';const list=state.invoices.filter(i=>(s==='All statuses'||i.status===s)&&[i.number,i.client,i.description].join(' ').toLowerCase().includes(q));$('#invoice-table').innerHTML=tableFor(list,'invoices')||'<div class="empty-state">No invoices found.</div>'}
document.addEventListener('submit',e=>{
 if(e.target.id==='assistant-form'){e.preventDefault();askAssistant($('#assistant-prompt').value);return}
 if(e.target.id==='settings-form'){e.preventDefault();const f=new FormData(e.target);state.company=f.get('company');state.owner=f.get('owner');state.industry=f.get('industry');state.settings.currency=f.get('currency');state.settings.businessEmail=f.get('businessEmail');state.settings.website=f.get('website');state.settings.showPromo=f.has('showPromo');state.settings.notifications=f.has('notifications');state.settings.aiEnabled=f.has('aiEnabled');save();renderNav();renderView();toast('Settings saved');return}
});
$('#mobile-menu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));
$('#hide-promo').addEventListener('click',()=>{state.settings.showPromo=false;save();renderNav();renderView();toast('Promotion hidden. Re-enable it in Settings.')});
$('#notifications').addEventListener('click',()=>handleAction('notifications'));
$('#profile-menu').addEventListener('click',()=>handleAction('profile-menu'));
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape'){$('#sidebar').classList.remove('open');if($('#modal')?.open)$('#modal').close();}if(e.key==='Enter'&&e.target.id==='global-search'){const q=e.target.value.toLowerCase();const c=state.contacts.find(c=>[c.name,c.company,c.email].join(' ').toLowerCase().includes(q));if(c){selectedContact=c.id;renderView();$('#global-results')?.remove()}}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(v&&v!==currentView){currentView=v;selectedContact=null;renderNav();renderView()}});
async function bootWorkspace(){
 try{
  const meRes=await fetch('/api/me',{credentials:'same-origin',cache:'no-store'});
  const me=await meRes.json();
  if(!me.user){window.location.replace('login.html');return;}
  state.owner=me.user.name||'';state.email=me.user.email||'';state.company=me.user.company||'';
  const stateRes=await fetch('/api/state',{credentials:'same-origin',cache:'no-store'});
  if(stateRes.ok){const payload=await stateRes.json();if(payload.state&&typeof payload.state==='object'){
   const remote=payload.state;
   state={...structuredClone(seed),...remote,owner:me.user.name||remote.owner||'',email:me.user.email||remote.email||'',company:me.user.company||remote.company||'',settings:{...seed.settings,...(remote.settings||{})},contacts:Array.isArray(remote.contacts)?remote.contacts:[],bookings:Array.isArray(remote.bookings)?remote.bookings:[],invoices:Array.isArray(remote.invoices)?remote.invoices:[],payments:Array.isArray(remote.payments)?remote.payments:[],employees:Array.isArray(remote.employees)?remote.employees:[],tasks:Array.isArray(remote.tasks)?remote.tasks:[],activities:Array.isArray(remote.activities)?remote.activities:[],campaigns:Array.isArray(remote.campaigns)?remote.campaigns:[]};
  } else {localStorage.removeItem('biab-demo-v1');localStorage.setItem(STORAGE,JSON.stringify(state));}
  }
  $('#profile-name').textContent=state.owner||'Business Owner';
  $('#profile-avatar').textContent=initials(state.owner)||'?' ;
  renderNav();renderView();
 }catch(error){console.error('Workspace could not be loaded',error);renderNav();renderView();toast('Could not connect to the server. Your empty workspace is shown locally.',true)}
}
bootWorkspace();
})();